def transform(grid):
    from collections import Counter, deque

    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue

            cells = []
            q = deque([(r, c)])
            seen.add((r, c))
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if (0 <= ny < h and 0 <= nx < w and
                            grid[ny][nx] != 0 and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        q.append((ny, nx))

            r0 = min(y for y, x in cells)
            r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells)
            c1 = max(x for y, x in cells)

            layers = {}
            for y, x in cells:
                depth = min(y - r0, r1 - y, x - c0, c1 - x)
                layers.setdefault(depth, []).append(grid[y][x])

            ordered = []
            for depth in sorted(layers):
                color = Counter(layers[depth]).most_common(1)[0][0]
                if not ordered or color != ordered[-1]:
                    ordered.append(color)

            mapping = dict(zip(ordered, reversed(ordered)))
            for y, x in cells:
                out[y][x] = mapping.get(grid[y][x], grid[y][x])

    return out
